const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function safe(value, fallback = null) {
  return value === undefined || value === null || value === "" ? fallback : value;
}

function makeDraftId(eventId) {
  const base = eventId || "unknown_event";
  const suffix = Date.now().toString(36);
  return `draft_${base}_${suffix}`.replace(/[^a-zA-Z0-9_]/g, "_");
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C4-M",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        draft_package: null,
        approval_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C4-M will not create draft package when upstream AI step failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (!source.ai_result || typeof source.ai_result !== "object") {
  return fail({
    code: "MISSING_AI_RESULT",
    message: "input.ai_result is required."
  });
}

if (source.ai_result.status !== "completed" && source.ai_result.status !== "completed_unparsed") {
  return fail({
    code: "AI_RESULT_NOT_COMPLETED",
    message: "input.ai_result.status must be completed or completed_unparsed.",
    details: [{ ai_status: source.ai_result.status || null }]
  });
}

if (!config.draft_type) {
  return fail({
    code: "MISSING_DRAFT_TYPE",
    message: "config.draft_type is required."
  });
}

if (!config.approval_type) {
  return fail({
    code: "MISSING_APPROVAL_TYPE",
    message: "config.approval_type is required."
  });
}

if (!config.reviewer_email) {
  return fail({
    code: "MISSING_REVIEWER_EMAIL",
    message: "config.reviewer_email is required."
  });
}

const aiJson = source.ai_result.parsed_json || {};
const draftId = makeDraftId(source.event_id);
const createdAt = nowIso();

const title =
  aiJson.draft_title ||
  aiJson.title ||
  aiJson.email_subject ||
  `${config.draft_type} draft`;

const summary =
  aiJson.draft_summary ||
  aiJson.summary ||
  aiJson.description ||
  source.ai_result.content ||
  "";

const draftPackage = {
  draft_id: draftId,
  draft_type: config.draft_type,
  draft_status: config.draft_status || "needs_review",
  draft_title: title,
  draft_summary: summary,
  draft_content: {
    raw_content: source.ai_result.content || null,
    parsed_json: source.ai_result.parsed_json || null
  },
  ai_metadata: {
    provider: source.ai_result.provider || null,
    model: source.ai_result.model || null,
    task_type: source.ai_result.task_type || null,
    usage: source.ai_result.usage || null,
    finish_reason: source.ai_result.finish_reason || null
  },
  owner: config.owner || "unassigned",
  priority: config.priority || "normal",
  created_at: createdAt,
  updated_at: createdAt
};

const approvalTitle = config.approval_title || `Review ${config.draft_type} draft: ${title}`;

const approvalHandoff = {
  next_component: "C2-O",
  input: {
    success: true,
    component_id: "C4-M",
    component_version: "v1",
    event_id: source.event_id || null,
    event_type: source.event_type || null,
    payload: {
      draft_id: draftPackage.draft_id,
      draft_type: draftPackage.draft_type,
      draft_title: draftPackage.draft_title,
      draft_summary: draftPackage.draft_summary,
      draft_status: draftPackage.draft_status,
      draft_content: draftPackage.draft_content,
      owner: draftPackage.owner,
      priority: draftPackage.priority
    },
    metadata: {
      source_component: source.component_id || null,
      source_event_type: source.event_type || null,
      generated_at: createdAt
    },
    error: null,
    next_action: "request_approval"
  },
  config: {
    approval_type: config.approval_type,
    approval_title: approvalTitle,
    reviewer_email: config.reviewer_email,
    approval_actions: config.approval_actions || ["approve", "reject", "revise"],
    approval_context_fields: [
      "payload.draft_id",
      "payload.draft_type",
      "payload.draft_title",
      "payload.draft_summary",
      "payload.draft_status"
    ],
    default_next_action: "notify_reviewer"
  }
};

return [
  {
    json: {
      success: true,
      component_id: "C4-M",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      draft_package: draftPackage,
      approval_handoff: approvalHandoff,
      source_result: source,
      error: null,
      next_action: config.default_next_action || "request_approval"
    }
  }
];
